public class ReservoirPickerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> items = java.util.Arrays.asList(
                "ann", "bob", "cid", "dee", "eve", "fay", "gus");

        try {
            check("sampleOne(seed 1)", "gus", ReservoirPicker.sampleOne(items, 1L));
            check("sampleOne(seed 5)", "bob", ReservoirPicker.sampleOne(items, 5L));
            check("sampleOne(seed 2024)", "eve", ReservoirPicker.sampleOne(items, 2024L));
            check("a one-item list always yields that item", "solo",
                    ReservoirPicker.sampleOne(java.util.Arrays.asList("solo"), 5L));
            check("an empty list yields null", null,
                    ReservoirPicker.sampleOne(new java.util.ArrayList<String>(), 5L));
            check("a null list yields null", null, ReservoirPicker.sampleOne(null, 5L));
            check("sampleMany(seed 100, 8 trials)",
                    "[fay, eve, eve, bob, ann, fay, fay, dee]",
                    String.valueOf(ReservoirPicker.sampleMany(items, 100L, 8)));
            check("same seed repeats the same pick",
                    ReservoirPicker.sampleOne(items, 11L),
                    ReservoirPicker.sampleOne(items, 11L));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

