/**
 * Reservoir sampling of a single item from a list.
 */
public class ReservoirPicker {

    public static String sampleOne(java.util.List<String> items, long seed) {
        if (items == null || items.isEmpty()) {
            return null;
        }
        java.util.Random rng = new java.util.Random(seed);
        String kept = null;
        for (int i = 0; i < items.size(); i++) {
            if (rng.nextInt(i + 1) == 0) {
                kept = items.get(i);
            }
        }
        return kept;
    }

    public static java.util.List<String> sampleMany(java.util.List<String> items, long seed, int trials) {
        java.util.List<String> results = new java.util.ArrayList<>();
        for (int t = 0; t < trials; t++) {
            results.add(sampleOne(items, seed + t));
        }
        return results;
    }
}
